async function hub(method: string, path: string, token?: string, body?: string): Promise<{ status: number; json: any }> {
  const response = await fetch(`${HUB}${path}`, { method, headers: { ...(body === undefined ? {} : { "content-type": "application/json" }), ...(token ? { authorization: `Bearer ${token}` } : {}) }, ...(body === undefined ? {} : { body }), signal: AbortSignal.timeout(120_000) }).catch((error: unknown) => {
