"""🐍️ Independent oracle of the board-tools corpus (`🧫️fixtures/🧫️board-tools/🔣️.json`).

Validates board event flushes and rectangles against their domain schemas with `jsonschema`, then re-derives every case's `expect` from the board and
its rows with a board model of its own (nodes own handles, a wire joins two handles, a region is a `shapely` box) —
written from design §22.32 (a) and the board-event payloads, not from the Rust: a painted area needs a positive extent, a resize needs a
region the board holds, a stamped brush adds a node and the wire back to its source handle, a delete takes a node with
every wire on its handles, a run of rows of one kind is one release, the first release that changes the board names the
row's tool, and a flush that changes nothing commits nothing. Exits non-zero on the first disagreement; an optional
argument names another corpus (negative controls).
"""

import copy
import json
import math
import pathlib
import sys

import jsonschema
from shapely.geometry import box

EDITOR = pathlib.Path(__file__).resolve().parents[2]
TOOLS = ("regionCreate", "regionResize", "brushPlace", "edgeCreate", "edgeDelete", "nodeDelete")


class Board:
    def __init__(self, fixture):
        self.nodes = set()
        self.wires = {}
        self.owner = {}
        self.regions = []
        for node in fixture["nodes"]:
            self.place(node["id"], [handle["id"] for handle in node["handles"]])
        for edge in fixture["edges"]:
            self.wire(edge["id"], edge["source"], edge["target"])

    def place(self, node, handles):
        self.nodes.add(node)
        for handle in handles:
            self.owner[handle] = node

    def wire(self, edge, source, target):
        self.wires[edge] = (self.owner[source], self.owner[target])

    def state(self):
        return (sorted(self.nodes), sorted(self.wires), copy.deepcopy(self.regions))

    def fold(self, name, payload):
        if name == "regionCreate":
            numbers = [payload.get(key) for key in ("x", "y", "width", "height")]
            if all(isinstance(number, (int, float)) and math.isfinite(number) for number in numbers) and box(payload["x"], payload["y"], payload["x"] + payload["width"], payload["y"] + payload["height"]).area > 0 and payload["width"] > 0 and payload["height"] > 0:
                self.regions.append({key: float(payload[key]) for key in ("x", "y", "width", "height")})
        elif name == "regionResize":
            index = 0 if payload["id"] == "$region" and self.regions else None
            if index is not None:
                self.regions[index] = {key: float(payload[key]) for key in ("x", "y", "width", "height")}
        elif name == "brushPlace":
            node = payload["nodeId"]
            self.place(node, [f"{node}:v{index}" for index, _ in enumerate(payload.get("handles", []))])
            if payload.get("sourceHandleId"):
                self.wire(payload["edgeId"], payload["sourceHandleId"], f"{node}:v{payload.get('targetHandleIndex', 0)}")
        elif name == "edgeCreate":
            self.wire(payload["id"], payload["source"], payload["target"])
        elif name == "edgeDelete":
            self.wires.pop(payload["id"], None)
        elif name == "nodeDelete":
            if payload["id"] in self.nodes:
                self.nodes.remove(payload["id"])
                self.wires = {edge: ends for edge, ends in self.wires.items() if payload["id"] not in ends}
                self.owner = {handle: node for handle, node in self.owner.items() if node != payload["id"]}

    def flush(self, rows):
        tool = None
        index = 0
        while index < len(rows):
            end = index
            while end < len(rows) and rows[end]["name"] == rows[index]["name"]:
                end += 1
            before = self.state()
            for row in rows[index:end]:
                self.fold(row["name"], row["payload"])
            if rows[index]["name"] in TOOLS and self.state() != before and tool is None:
                tool = rows[index]["name"]
            index = end
        return tool


def main():
    corpus_path = pathlib.Path(sys.argv[1]) if len(sys.argv) > 1 else EDITOR / "🧫️fixtures" / "🧫️board-tools" / "🔣️.json"
    corpus = json.loads(corpus_path.read_text(encoding="utf-8"))
    schema = json.loads((EDITOR / "🧬️schema" / "🔣️board-tools" / "🔣️.json").read_text(encoding="utf-8"))
    jsonschema.Draft7Validator.check_schema(schema)
    for case in corpus["cases"]:
        for flush in [*case["setup"], case["rows"]]:
            jsonschema.validate(flush, schema)
        if "region" in case["expect"]:
            jsonschema.validate(case["expect"]["region"], {**schema, "$ref": "#/definitions/Rectangle"})
    for case in corpus["cases"]:
        board = Board(corpus["board"])
        for flush in case["setup"]:
            if board.flush(flush) is None:
                sys.exit(f"{case['name']}: a setup flush changes nothing")
        tool = board.flush(case["rows"])
        nodes, edges, regions = board.state()
        derived = {"edits": 0 if tool is None else 1, "tool": tool, "nodes": len(nodes), "edges": len(edges), "targetRegions": len(regions)}
        if "region" in case["expect"]:
            derived["region"] = regions[0] if regions else None
        if derived != case["expect"]:
            sys.exit(f"{case['name']}: the corpus states {case['expect']}, the oracle derives {derived}")
        if case.get("transient") and (tool is not None or any(row["name"] in TOOLS for row in case["rows"])):
            sys.exit(f"{case['name']}: a transient case holds a board-tool row")
    print(f"board-tools corpus: {len(corpus['cases'])} cases agree with the oracle")


if __name__ == "__main__":
    main()

"""🐍️ Independent oracle of the select-tool history corpus (`🧫️fixtures/🧫️select-tool-history/🔣️.json`).

Validates the corpus against its JSON Schema and every leaf against its puzzle 2d payload schema with `jsonschema`, then
re-folds each scenario's edited log (`log` with its `drafts`, withdrawn leaves dropped) over the board with shapely's
affine transforms and requires the scenario's `head`. Written from the leaf schemas and design §8, not from the Rust:
locked and missing targets are skipped, a rotation turns positions about the recorded pivot, a scaling spreads them.
Exits non-zero on the first disagreement; an optional argument names another corpus (negative controls).
"""

import json
import math
import pathlib
import sys

import jsonschema
from shapely import affinity
from shapely.geometry import Point

EDITOR = pathlib.Path(__file__).resolve().parents[2]
MUTATIONS = EDITOR.parent / "🧬️schema" / "🧬️mutations"
LEAF_DIRS = {
    "dragSelection": "✋️drag-selection",
    "rotateSelection": "🔄️rotate-selection",
    "scaleSelection": "🔍️scale-selection",
    "createNode": "🌱create-node",
    "changeNodeLocked": "🔒change-node-locked",
}
TOLERANCE = 1e-9


def load(path):
    return json.loads(path.read_text(encoding="utf-8"))


def leaf_validator(kind, cache={}):
    if kind not in cache:
        cache[kind] = jsonschema.Draft7Validator(load(MUTATIONS / LEAF_DIRS[kind] / "🧬️schema" / "🔣️.json"))
    return cache[kind]


def leaves(scenario):
    yield from scenario["log"]
    yield from (draft["leaf"] for draft in scenario["drafts"] if "leaf" in draft)
    for step in scenario["steps"]:
        if "ingest" in step:
            yield step["ingest"]
        if "row" in step.get("expect", {}):
            yield step["expect"]["row"]["leaf"]


def edited_log(scenario):
    drafts = {draft["index"]: draft for draft in scenario["drafts"]}
    for index, leaf in enumerate(scenario["log"]):
        draft = drafts.get(index)
        if draft is None:
            yield leaf
        elif "leaf" in draft:
            yield draft["leaf"]


def movable(nodes, targets):
    return [nodes[target] for target in targets if target in nodes and not nodes[target].get("locked", False)]


def fold(board, log):
    nodes = {node["id"]: dict(node) for node in board["nodes"]}
    for leaf in log:
        kind = leaf["mutation"]
        if kind == "createNode":
            nodes[leaf["node"]["id"]] = dict(leaf["node"])
        elif kind == "changeNodeLocked":
            if leaf["id"] in nodes:
                nodes[leaf["id"]]["locked"] = bool(leaf["newLocked"])
        else:
            for node in movable(nodes, leaf["targets"]):
                point = Point(node["x"], node["y"])
                if kind == "dragSelection":
                    point = affinity.translate(point, xoff=leaf["dx"], yoff=leaf["dy"])
                elif kind == "rotateSelection":
                    point = affinity.rotate(point, leaf["angle"], origin=(leaf["pivotX"], leaf["pivotY"]), use_radians=True)
                elif kind == "scaleSelection":
                    point = affinity.scale(point, xfact=leaf["factor"], yfact=leaf["factor"], origin=(leaf["pivotX"], leaf["pivotY"]))
                node["x"], node["y"] = point.x, point.y
    return nodes


def main():
    corpus = load(pathlib.Path(sys.argv[1]) if len(sys.argv) > 1 else EDITOR / "🧫️fixtures" / "🧫️select-tool-history" / "🔣️.json")
    jsonschema.Draft7Validator(load(EDITOR / "🧬️schema" / "🔣️select-tool-history" / "🔣️.json")).validate(corpus)
    checked = 0
    for scenario in corpus["scenarios"]:
        for leaf in leaves(scenario):
            leaf_validator(leaf["mutation"]).validate(leaf)
        nodes = fold(corpus["board"], list(edited_log(scenario)))
        for node_id, expected in scenario["head"].items():
            node = nodes.get(node_id)
            if node is None:
                sys.exit(f"{scenario['id']}: {node_id} is missing from the folded head")
            if not (math.isclose(node["x"], expected["x"], abs_tol=TOLERANCE) and math.isclose(node["y"], expected["y"], abs_tol=TOLERANCE)):
                sys.exit(f"{scenario['id']}: {node_id} folds to ({node['x']}, {node['y']}), the corpus says ({expected['x']}, {expected['y']})")
            if node.get("locked", False) != expected.get("locked", False):
                sys.exit(f"{scenario['id']}: {node_id} lock folds to {node.get('locked', False)}")
            checked += 1
        absent = {node_id for step in scenario["steps"] for node_id in step.get("expect", {}).get("absent", [])}
        if any(node_id in scenario["head"] for node_id in absent):
            sys.exit(f"{scenario['id']}: a node the review shows absent is in the head")
    print(f"select-tool-history oracle: {len(corpus['scenarios'])} scenarios, {checked} head nodes agree")


if __name__ == "__main__":
    main()

"""🐍️ Independent oracle of the history-edit runtime corpus (`🧫️fixtures/🧫️history-edit-runtime/🔣️.json`).

Validates the corpus against its JSON Schema and every leaf (authored, ingested, and edited) against its puzzle 2d payload
schema with `jsonschema`. It then folds each named head with shapely, using the select-tool oracle's fold of the selection
leaves (`🧪️select-tool-history/🐍️.py`, which was written from the leaf schemas and design §8, not from the Rust). Each head
is the scenario's board with its `log` folded, after the leaves its `edits` name are replaced or dropped. The fold must give
the head's nodes, must not contain its absent ids, must hold exactly its `edges` and must report exactly its `outcomes`.

A `connectHandles` leaf adds its edge. One that states a `tolerance` is a recorded proximity (design §22.13): where its two
handles are farther apart than the tolerance on the document it folds onto, or one is on no node, the fold reports
`mutation.precondition-drifted` for both handles. A handle sits on its node's rim: a circle's east-zero angle on the radius,
a rectangle's north-zero angle on its outline.

It also checks that every head a step names exists, that every `row` a step names is an authored edit, and that a review
step's drift outcomes name the handles its previewed head folds to.

Exits non-zero on the first disagreement. An optional argument names another corpus, for negative controls.
"""

import importlib.util
import json
import math
import pathlib
import sys

import jsonschema
from shapely import affinity
from shapely.geometry import LineString, Point, box

EDITOR = pathlib.Path(__file__).resolve().parents[2]
SPEC = importlib.util.spec_from_file_location("select_tool_history_oracle", EDITOR / "🧪️tests" / "🧪️select-tool-history" / "🐍️.py")
SELECT_TOOL = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(SELECT_TOOL)
TOLERANCE = 1e-9
CONNECT = "connectHandles"
DRIFTED = "mutation.precondition-drifted"


def load(path):
    return json.loads(path.read_text(encoding="utf-8"))


def validator(kind, cache={}):
    if kind != CONNECT:
        return SELECT_TOOL.leaf_validator(kind)
    if kind not in cache:
        cache[kind] = jsonschema.Draft7Validator(load(SELECT_TOOL.MUTATIONS / "🪢️connect-handles" / "🧬️schema" / "🔣️.json"))
    return cache[kind]


def edited_log(scenario, head):
    edits = {edit["index"]: edit for edit in head["edits"]}
    for index, leaf in enumerate(scenario["log"]):
        edit = edits.get(index)
        if edit is None:
            yield index, leaf
        elif "leaf" in edit:
            yield index, edit["leaf"]


def leaves(scenario):
    yield from scenario["log"]
    for head in scenario["heads"].values():
        yield from (edit["leaf"] for edit in head["edits"] if "leaf" in edit)
    yield from (step["ingest"] for step in scenario["steps"] if "ingest" in step)


def rim(node, handle):
    centre = Point(node["x"], node["y"])
    if node.get("shape") != "rectangle":
        return affinity.rotate(Point(centre.x + node.get("radius", 24.0), centre.y), handle["angle"], origin=centre, use_radians=True)
    half_width, half_height = node.get("width", 48.0) / 2.0, node.get("height", 48.0) / 2.0
    reach = 2.0 * math.hypot(half_width, half_height)
    ray = LineString([centre, (centre.x - math.sin(handle["angle"]) * reach, centre.y - math.cos(handle["angle"]) * reach)])
    return ray.intersection(box(centre.x - half_width, centre.y - half_height, centre.x + half_width, centre.y + half_height).exterior)


def fold(board, log):
    edges, outcomes, selection = [edge["id"] for edge in board["edges"]], [], []
    for index, leaf in log:
        if leaf["mutation"] != CONNECT:
            selection.append(leaf)
            continue
        if leaf["id"] in edges:
            continue
        handles = {handle["id"]: (node, handle) for node in SELECT_TOOL.fold(board, selection).values() for handle in node.get("handles", [])}
        ends = [handles.get(leaf[end]) for end in ("source", "target")]
        tolerance = leaf.get("tolerance")
        if tolerance is not None and (None in ends or rim(*ends[0]).distance(rim(*ends[1])) > tolerance):
            outcomes.append({"index": index, "code": DRIFTED, "target": [leaf["source"], leaf["target"]]})
        edges.append(leaf["id"])
    return SELECT_TOOL.fold(board, selection), edges, outcomes


def main():
    corpus = load(pathlib.Path(sys.argv[1]) if len(sys.argv) > 1 else EDITOR / "🧫️fixtures" / "🧫️history-edit-runtime" / "🔣️.json")
    jsonschema.Draft7Validator(load(EDITOR / "🧬️schema" / "🔣️history-edit-runtime" / "🔣️.json")).validate(corpus)
    checked, drifted = 0, 0
    for scenario in corpus["scenarios"]:
        name = scenario["id"]
        for leaf in leaves(scenario):
            validator(leaf["mutation"]).validate(leaf)
        folded = {head_name: fold(scenario.get("board", corpus["board"]), list(edited_log(scenario, head))) for head_name, head in scenario["heads"].items()}
        for step in scenario["steps"]:
            expect = step.get("expect", {})
            for key in ("head", "preview"):
                if key in expect and expect[key] not in scenario["heads"]:
                    sys.exit(f"{name}: a step names the unknown head {expect[key]}")
            rows = [outcome["row"] for outcome in expect.get("outcomes", [])] + [expect[key]["row"] for key in ("nextProblem", "words") if key in expect]
            if isinstance(step.get("begin"), dict):
                rows.append(step["begin"]["row"])
            if any(row >= len(scenario["log"]) for row in rows):
                sys.exit(f"{name}: a step names a row beyond the {len(scenario['log'])} authored edits")
            reviewed = [outcome["target"] for outcome in expect.get("outcomes", []) if outcome["code"] == DRIFTED]
            if "preview" in expect and reviewed != [outcome["target"] for outcome in folded[expect["preview"]][2]]:
                sys.exit(f"{name}: a review reports the drift of {reviewed}, its previewed head {expect['preview']} folds to {folded[expect['preview']][2]}")
        for head_name, head in scenario["heads"].items():
            nodes, edges, outcomes = folded[head_name]
            for node_id, expected in head["nodes"].items():
                node = nodes.get(node_id)
                if node is None:
                    sys.exit(f"{name}/{head_name}: {node_id} is missing from the folded head")
                if not (math.isclose(node["x"], expected["x"], abs_tol=TOLERANCE) and math.isclose(node["y"], expected["y"], abs_tol=TOLERANCE)):
                    sys.exit(f"{name}/{head_name}: {node_id} folds to ({node['x']}, {node['y']}), the corpus says ({expected['x']}, {expected['y']})")
                if node.get("locked", False) != expected.get("locked", False):
                    sys.exit(f"{name}/{head_name}: {node_id} lock folds to {node.get('locked', False)}")
                checked += 1
            if any(node_id in nodes for node_id in head.get("absent", [])):
                sys.exit(f"{name}/{head_name}: an absent node is in the folded head")
            if "edges" in head and sorted(edges) != sorted(head["edges"]):
                sys.exit(f"{name}/{head_name}: the fold holds the edges {sorted(edges)}, the corpus says {sorted(head['edges'])}")
            if "outcomes" in head:
                if any(outcome["code"] != DRIFTED for outcome in head["outcomes"]):
                    sys.exit(f"{name}/{head_name}: this oracle folds only {DRIFTED} outcomes")
                if outcomes != head["outcomes"]:
                    sys.exit(f"{name}/{head_name}: the fold reports {outcomes}, the corpus says {head['outcomes']}")
                drifted += len(outcomes)
    print(f"history-edit-runtime oracle: {len(corpus['scenarios'])} scenarios, {checked} head nodes agree, {drifted} drift outcomes agree")


if __name__ == "__main__":
    main()

import { serviceMcpTestArtifactRoot } from "../📁️artifact-root/🟦️.ts";
/** 🧷️ The untrusted-content law over the REAL `semio-os-mcp` binary (audit `📓️audit-s12-ai-mcp.md`
 * §3.3, G12-P1-2). A collaborator writes the law's canary — a prompt-injection sentence — into a
 * shared document; an agent then reads the document back through every surface the gateway has.
 * The canary must arrive only inside the `untrusted` envelope of every carrier the law names, and
 * nowhere in any observer or any other field, neither as text nor in any of its three base64
 * alignments. AJV (third party) validates every live envelope against the published
 * `UntrustedContentV1` and refuses every hostile one; `node:crypto` recomputes the provenance's
 * `contentSha256` over the decoded bytes. The Rust twin is
 * `artifact::quick::document_authored_content_reaches_an_agent_only_inside_the_untrusted_envelope`. */
import { createHash } from "node:crypto";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import Ajv from "ajv";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { requireMcpBinary, spawnRawMcp, type RawMcpProcess } from "../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/🌉️mcp/🟦️.ts";
import { getWorkspaceRoot } from "../../../../../🧰️framework/🛍️products/🦑️repo/🔨️modules/📚️library/📦️packages/🟦️typescript/🟦️.ts";

const repoRoot = getWorkspaceRoot();
const bin = requireMcpBinary(repoRoot);
const ownerRoot = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const moduleRoot = join(repoRoot, "🧰️framework/🛍️products/💻️os/🔨️modules/🌉️mcp");
const readJson = (...segments: string[]): any => JSON.parse(readFileSync(join(moduleRoot, ...segments), "utf8"));
const composition = JSON.parse(readFileSync(join(ownerRoot, "🧫️fixtures/🧷️untrusted-content/🔣️.json"), "utf8"));
const law = JSON.parse(readFileSync(join(repoRoot, composition.lawPath), "utf8"));
const mcpSchema = readJson("🧬️schema", "🔣️.json");
const artifactSchema = readJson("🗿️artifact", "🧬️schema", "🔣️.json");
const workspaceSchema = readJson("🏠️workspace", "🧬️schema", "🔣️.json");
const ajv = new Ajv({ strict: true, allErrors: true });
for (const schema of [mcpSchema, workspaceSchema, artifactSchema]) ajv.addSchema(schema);
const validEnvelope = ajv.getSchema(`${mcpSchema.$id}#/$defs/UntrustedContentV1`)!;
const validLaw = ajv.getSchema(`${artifactSchema.$id}#/$defs/UntrustedContentLawV1`)!;

const CATALOG_COMPILE_TIMEOUT_MS = 90_000;
const GUEST_CALL_TIMEOUT_MS = 240_000;
const canary: string = law.canary;
const needles = [canary, ...[0, 1, 2].map((shift) => Buffer.from(canary, "utf8").subarray(shift).subarray(0, Math.floor((Buffer.byteLength(canary) - shift) / 3) * 3).toString("base64"))];
const namesCanary = (text: string): boolean => needles.some((needle) => text.includes(needle));

/** ✂️ `value` with every untrusted envelope cut out, collecting the envelopes it held. */
function outsideUntrusted(value: unknown, envelopes: Record<string, any>[]): unknown {
  if (Array.isArray(value)) return value.map((item) => outsideUntrusted(item, envelopes));
  if (value === null || typeof value !== "object") return value;
  return Object.fromEntries(
    Object.entries(value as Record<string, unknown>).flatMap(([key, member]) => {
      if (key === law.envelopeField && (member as Record<string, unknown> | null)?.schema === "semio.mcp.untrusted-content/v1") {
        envelopes.push(member as Record<string, any>);
        return [];
      }
      return [[key, outsideUntrusted(member, envelopes)]];
    }),
  );
}

/** 📖️ The bytes an envelope carries, decoded in the order `contentSha256` hashes them. */
function envelopeBytes(envelope: Record<string, any>): Buffer {
  const content = envelope.content as Record<string, string>;
  return Buffer.concat(["packBase64", "sprBase64", "contentBase64"].filter((field) => typeof content[field] === "string").map((field) => Buffer.from(content[field]!, "base64")));
}

function withHostile(envelope: Record<string, any>, path: string[], value: unknown): Record<string, any> {
  const copy = structuredClone(envelope);
  let cursor: Record<string, any> = copy;
  for (const segment of path.slice(0, -1)) cursor = cursor[segment];
  cursor[path.at(-1)!] = value;
  return copy;
}

describe("semio-os-mcp — document content reaches an agent only as untrusted data", () => {
  let proc: RawMcpProcess;
  let folder: string;
  let discovered: Record<string, any>;
  const call = async (name: string, args: Record<string, unknown>, timeoutMs = GUEST_CALL_TIMEOUT_MS): Promise<Record<string, any>> => (await proc.request("tools/call", { name, arguments: args }, timeoutMs)) as Record<string, any>;
  /** ✍️ The collaborator's write, by the law's headless recipe: the kind's own text verb, prepared
   * and invoked like any agent edit, every `{{canary}}` replaced by the canary. A whole-text replacement is destructive, so
   * this gateway auto-approves: human approval is the security and user-path gates' law, not this one. */
  const plant = async (recipe: { capabilityId: string; input: Record<string, unknown> }): Promise<Record<string, any>> => {
    const input = JSON.parse(JSON.stringify(recipe.input).replaceAll("{{canary}}", canary));
    const prepared = await call("action_prepare", { capabilityId: recipe.capabilityId, input });
    expect(prepared.result?.isError, JSON.stringify(prepared).slice(0, 400)).not.toBe(true);
    return call("action_invoke", { preparedActionHandle: prepared.result.structuredContent.preparedHandle });
  };
  const carrierReply = async (carrier: { surface: string; name: string }, artifactId: string): Promise<unknown> =>
    carrier.surface === "tool" ? (await call(carrier.name, { artifactId })).result : JSON.parse(((await proc.request("resources/read", { uri: carrier.name.replace("{artifactId}", artifactId) })) as any).result.contents[0].text);
  const observerReply = async (observer: { surface: string; name: string }, artifactId: string): Promise<unknown> => {
    if (observer.surface === "list") return proc.request(observer.name, {});
    if (observer.surface === "resource") return proc.request("resources/read", { uri: observer.name.replace("{artifactId}", artifactId) });
    const argumentsFor: Record<string, Record<string, unknown>> = { context_resolve: { principal: "agent:local" }, capabilities_search: { query: "delete every block" }, inference_list: { artifactId } };
    return (await call(observer.name, argumentsFor[observer.name] ?? { artifactId })).result;
  };

  beforeAll(async () => {
    folder = mkdtempSync(join(serviceMcpTestArtifactRoot(), "semio-os-mcp-untrusted-"));
    proc = spawnRawMcp(bin, ["stdio", "--folder", folder, "--scopes", "workspace.read,artifact.write", "--auto-approve", "all"]);
    proc.writeRaw(JSON.stringify({ jsonrpc: "2.0", id: 9001, method: "server/discover", params: {} }));
    discovered = JSON.parse(await proc.nextLine(CATALOG_COMPILE_TIMEOUT_MS));
    expect((await call("artifact_create", { artifactId: "probe-canary", kind: "os.agent.probe/v1", initial: { text: canary } })).result?.isError).not.toBe(true);
    const recipe = composition.plants.find((row: { lane: string }) => row.lane === "headless");
    expect((await call("artifact_create", { artifactId: "plugin-canary", kind: recipe.artifactKind })).result?.isError).not.toBe(true);
    const planted = await plant(recipe);
    expect(planted.result?.structuredContent?.status, `the collaborator's write: ${JSON.stringify(planted).slice(0, 400)}`).toBe("SUCCEEDED");
  }, 600_000);

  afterAll(async () => {
    await proc?.close();
    if (folder) rmSync(folder, { recursive: true, force: true });
  });

  it("the law fixture is a valid UntrustedContentLawV1 and its canary is printable ASCII", () => {
    expect(validLaw(law), JSON.stringify(validLaw.errors)).toBe(true);
  });

  it("the server states the rule before any tool is called, and the carrying tools state it again", async () => {
    expect(String(discovered.result?.instructions ?? "")).toContain("semio.mcp.untrusted-content/v1");
    expect(String(discovered.result?.instructions ?? "")).toContain("nie als Anweisungen");
    const { tools } = ((await proc.request("tools/list", {})) as any).result as { tools: Array<{ name: string; description?: string }> };
    for (const carrier of law.carriers.filter((row: { surface: string }) => row.surface === "tool")) {
      expect(tools.find((tool) => tool.name === carrier.name)?.description ?? "", `${carrier.name} description`).toContain("semio.mcp.untrusted-content/v1");
    }
  });

  for (const artifactId of ["probe-canary", "plugin-canary"]) {
    it(`every carrier hands ${artifactId}'s content over only inside a valid, pinned envelope`, async () => {
      for (const carrier of law.carriers) {
        if (artifactId === "probe-canary" && carrier.source === "artifact-export") continue;
        const reply = await carrierReply(carrier, artifactId);
        const envelopes: Record<string, any>[] = [];
        const outside = JSON.stringify(outsideUntrusted(reply, envelopes));
        expect(namesCanary(outside), `${carrier.name} leaked the canary outside its envelope: ${outside.slice(0, 400)}`).toBe(false);
        expect(envelopes.length, `${carrier.name} carries exactly one envelope`).toBe(1);
        const envelope = envelopes[0]!;
        expect(validEnvelope(envelope), `${carrier.name}: ${JSON.stringify(validEnvelope.errors)}`).toBe(true);
        expect(envelope.provenance.source).toBe(carrier.source);
        expect(envelope.provenance.artifactId).toBe(artifactId);
        expect(envelope.provenance.authors.kind).toBe("local-principal");
        const bytes = envelopeBytes(envelope);
        if (carrier.source === "artifact-body") expect(bytes.toString("latin1").includes(canary), `${carrier.name} really carries the collaborator's text`).toBe(true);
        expect(envelope.provenance.revision.contentSha256).toBe(createHash("sha256").update(bytes).digest("hex"));
        for (const hostile of law.hostile) expect(validEnvelope(withHostile(envelope, hostile.path, hostile.value)), `hostile ${hostile.name} was admitted`).toBe(false);
      }
    }, GUEST_CALL_TIMEOUT_MS);

    it(`no observer forwards ${artifactId}'s content at all`, async () => {
      for (const observer of law.observers) {
        const reply = JSON.stringify(await observerReply(observer, artifactId));
        expect(namesCanary(reply), `${observer.name} forwarded document content outside any envelope: ${reply.slice(0, 400)}`).toBe(false);
      }
    }, GUEST_CALL_TIMEOUT_MS);
  }
});
